import{_ as a,o as t,c as i,a8 as o}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ","lang":"en"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790353258000}'),n={name:"guide/faq.md"};function s(r,e,l,c,d,h){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJGQVElMjIlMkMlMjJsYW5nJTIyJTNBJTIyZW4lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1MzI1ODAwMCU3RA=="},[...e[0]||(e[0]=[o(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="how-does-this-module-perform" tabindex="-1">How does this module perform? <a class="header-anchor" href="#how-does-this-module-perform" aria-label="Permalink to &quot;How does this module perform?&quot;">​</a></h2><p>IP inspection and CC defense take constant time, other inspections take <code>O(nm)</code>, where <code>n</code> is the number of relevant rules and <code>m</code> is the time complexity to perform regular matching, but the results of this inspection are automatically cached after each inspection, so that the next time the same target is inspected, the cache can be used instead of checking all the rules. The result of the POST request body check is not cached.</p><h2 id="cache-policy" tabindex="-1">Cache Policy <a class="header-anchor" href="#cache-policy" aria-label="Permalink to &quot;Cache Policy&quot;">​</a></h2><p>LRU</p><h2 id="embedded-variables-and-directive-if" tabindex="-1">Embedded variables and directive <code>if</code> <a class="header-anchor" href="#embedded-variables-and-directive-if" aria-label="Permalink to &quot;Embedded variables and directive \`if\`&quot;">​</a></h2><p>In short, due to NGINX&#39;s state machine model, you cannot use any embedded variables from this module (such as <code>$waf_rule_type</code>) for the directive <code>if</code>, except for the parameter <code>if</code> of the directive <code>access_log</code>.</p><h2 id="ngx-http-access-module" tabindex="-1"><code>ngx_http_access_module</code> <a class="header-anchor" href="#ngx-http-access-module" aria-label="Permalink to &quot;\`ngx_http_access_module\`&quot;">​</a></h2><p>When this module is used with <code>ngx_http_access_module</code>, <code>ngx_http_access_module</code> will run before this module.</p><h2 id="post-inspection-failure" tabindex="-1">Post Inspection Failure <a class="header-anchor" href="#post-inspection-failure" aria-label="Permalink to &quot;Post Inspection Failure&quot;">​</a></h2><p>For performance reasons, this module will inspect whether it is in the memory before inspecting the request body. If it is, it will inspect normally, otherwise skip the inspection. You can try to edit nginx.conf.</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_body_buffer_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10M</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_body_in_file_only </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#client_body_buffer_size" target="_blank" rel="noreferrer">client_body_buffer_size</a> and <a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#client_body_in_file_only" target="_blank" rel="noreferrer">client_body_in_file_only</a>.</p><h2 id="can-i-change-the-rules-at-runtime" tabindex="-1">Can I change the rules at runtime? <a class="header-anchor" href="#can-i-change-the-rules-at-runtime" aria-label="Permalink to &quot;Can I change the rules at runtime?&quot;">​</a></h2><p>No, this module will only read the rules when nginx reads the configuration. nginx will read the configuration on startup and reload.</p><h2 id="is-ip-inspection-affected-by-cdn" tabindex="-1">Is IP inspection affected by CDN? <a class="header-anchor" href="#is-ip-inspection-affected-by-cdn" aria-label="Permalink to &quot;Is IP inspection affected by CDN?&quot;">​</a></h2><p>If you use the <a href="https://nginx.org/en/docs/http/ngx_http_realip_module.html" target="_blank" rel="noreferrer">ngx_http_realip_module</a> module to get the real IP, then this module will use the real IP for inspection.</p><h2 id="regular-expression-denial-of-service-redos" tabindex="-1">Regular expression Denial of Service (ReDoS) <a class="header-anchor" href="#regular-expression-denial-of-service-redos" aria-label="Permalink to &quot;Regular expression Denial of Service (ReDoS)&quot;">​</a></h2><blockquote><p>The regular expression denial of service (ReDoS) is an algorithmic complexity attack that produces a denial-of-service by providing a regular expression that takes a very long time to evaluate. <br><br><a href="https://en.wikipedia.org/wiki/ReDoS" target="_blank" rel="noreferrer">ReDoS - Wikipedia</a></p></blockquote><ul><li><p>This module uses the PCRE library to execute regular expressions. The PCRE library can specify the upper limit of the main loop counter at compile time and stop automatically when the upper limit is exceeded. The default limit is 500000. You can also adjust it manually at compile time, see the <a href="https://www.pcre.org/current/doc/html/pcre2build.html#SEC11" target="_blank" rel="noreferrer">pcre2 build man page</a>.</p></li><li><p>This module caches all regular inspections (except POST inspections), so that the next time you encounter a string for an attack, you do not need to execute the regular expression again without triggering the cache cleanup process.</p></li></ul><h2 id="fork-failed-while-spawning-worker-process-12-cannot-allocate-memory" tabindex="-1">fork() failed while spawning &quot;worker process&quot; (12: Cannot allocate memory) <a class="header-anchor" href="#fork-failed-while-spawning-worker-process-12-cannot-allocate-memory" aria-label="Permalink to &quot;fork() failed while spawning &quot;worker process&quot; (12: Cannot allocate memory)&quot;">​</a></h2><p>It may be caused by excessive use of <code>nginx -s reload</code>. The module requests some memory when reading the configuration, but somehow the memory is not released immediately after <code>nginx -s reload</code>, so frequent <code>nginx -s reload</code> in a short period of time will most likely cause this error.</p><h2 id="panic-unprotected-error-in-call-to-lua-api-attempt-to-index-a-nil-value" tabindex="-1">PANIC: unprotected error in call to Lua API (attempt to index a nil value) <a class="header-anchor" href="#panic-unprotected-error-in-call-to-lua-api-attempt-to-index-a-nil-value" aria-label="Permalink to &quot;PANIC: unprotected error in call to Lua API (attempt to index a nil value)&quot;">​</a></h2><p>Please check the version of <code>libmodsecurity</code>. After testing, <code>libmodsecurity v3.0.3</code> has this bug, please update to <code>libmodsecurity v3.0.5</code>.</p>`,24)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
